INSERT INTO senvo_outreach.company_knowledge (id, category, title, content, approved, updated_at) VALUES ('3643f716-fa30-421d-b02b-38e4aeb762f0', 'claim_boundary', 'Compliance & Engagement Integrity Guidelines', 'Strict compliance policy: All tax advisory strictly complies with Revenue Commissioners guidance. We do not promote aggressive tax avoidance schemes. Engagement fees are scoped transparently based on business turnover, transaction volumes, and statutory complexity following a formal discovery review.', 1, '2026-10-29T10:43:37.082Z') ON CONFLICT DO NOTHING;
