INSERT INTO senvo_outreach.messages (id, conversation_id, direction, sender_name, content, delivery_mode, status, is_ai_generated, metadata, created_at) VALUES ('4856380c-38e7-465c-873e-53576258770f', '457b7eaa-0dd6-447e-9a15-3768f923d28f', 'inbound', 'Dr. Fiona Gallagher', 'Website Inquiry: We are an Enterprise Ireland supported MedTech firm in Galway. We need guidance on R&D Tax Credit claims (Section 766 TCA 1997), grant claim audit verification, and BrightPay payroll for 28 scientists and staff.', 'simulated', 'delivered', 0, '{}', '2026-10-29T10:43:37.082Z') ON CONFLICT DO NOTHING;
INSERT INTO senvo_outreach.messages (id, conversation_id, direction, sender_name, content, delivery_mode, status, is_ai_generated, metadata, created_at) VALUES ('f6586d30-9159-474e-9187-6604f84eca5d', '457b7eaa-0dd6-447e-9a15-3768f923d28f', 'outbound', 'SENVO AI SDR', 'Dear Dr. Gallagher, Thank you for contacting SENVO. We have substantial experience with Enterprise Ireland client companies, specialized R&D tax credit technical-financial documentation under Section 766, and compliant Revenue-linked payroll. Our Life Sciences advisory lead has been assigned and will contact you directly.', 'simulated', 'delivered', 1, '{}', '2026-10-29T10:43:37.082Z') ON CONFLICT DO NOTHING;
INSERT INTO senvo_outreach.messages (id, conversation_id, direction, sender_name, content, delivery_mode, status, is_ai_generated, metadata, created_at) VALUES ('e7e22e6f-72e1-4942-8fc3-b240af4d0db5', '017b408e-dd7e-446e-b314-bbcdf2c5bb74', 'outbound', 'SENVO Advisory', 'Hi Ciaran, noticed your recent team expansion at Horizon Software Technologies. With tech firms scaling in Dublin, ensuring seamless ERP integration and securing qualified senior finance talent is crucial...', 'simulated', 'delivered', 0, '{}', '2026-10-29T10:43:37.082Z') ON CONFLICT DO NOTHING;
