-- Seed ai_assessments (5 records)
INSERT INTO senvo_outreach.ai_assessments (id, conversation_id, message_id, lead_id, intent, requested_service, summary, confidence, suggested_reply, suggested_next_action, human_review_required, review_status, raw_response, created_at) VALUES ('1eb9f74f-6c97-4809-8ad0-906048e0ee9f', '035b7138-05ea-4106-a525-e6bfb15e0313', '475432c8-bc27-49a3-80e0-ba37dcd89d0b', '3d91b9a6-e680-4382-9fd7-d2298c943a6e', 'qualified_demo_request', 'Outsourced Bookkeeping, VAT3 & Statutory Audit Prep', 'Declan Murphy (Apex Logistics) requires outsourced monthly bookkeeping, cross-border VAT3 reconciliations, and statutory audit file preparation due to bottlenecks with incumbent provider.', 0.96, 'Dear Declan, Thank you for reaching out. SENVO specializes in logistics and freight sector accounting, including complex post-Brexit cross-border VAT3 reconciliations, postponed accounting mechanisms, and streamlined monthly management accounts. We would be delighted to connect this Thursday at 2:30 PM. I will send a calendar invitation with an outline of our discovery process.', 'Schedule discovery video meeting with Declan Murphy for Thursday 2:30 PM (Senior Client Partner)', 1, 'approved', NULL, '2026-10-29T10:43:37.082Z') ON CONFLICT DO NOTHING;
INSERT INTO senvo_outreach.ai_assessments (id, conversation_id, message_id, lead_id, intent, requested_service, summary, confidence, suggested_reply, suggested_next_action, human_review_required, review_status, raw_response, created_at) VALUES ('001c12f4-165a-4751-83f3-800dbfd4f55d', '457b7eaa-0dd6-447e-9a15-3768f923d28f', 'f6586d30-9159-474e-9187-6604f84eca5d', '995bfee0-d502-4951-8aaa-e6de5ce98c22', 'enterprise_inquiry', 'R&D Tax Credit Advisory & Payroll Bureau', 'High-value Enterprise Ireland client: 28-person MedTech DAC requiring Section 766 R&D tax credit claim preparation and BrightPay payroll compliance.', 0.98, 'Dear Dr. Gallagher, Thank you for contacting SENVO. We have substantial experience with Enterprise Ireland client companies, specialized R&D tax credit technical-financial documentation under Section 766, and compliant Revenue-linked payroll.', 'Direct Executive Handoff to Tax Director (Life Sciences Practice)', 0, 'approved', NULL, '2026-10-29T10:43:37.082Z') ON CONFLICT DO NOTHING;
INSERT INTO senvo_outreach.ai_assessments (id, conversation_id, message_id, lead_id, intent, requested_service, summary, confidence, suggested_reply, suggested_next_action, human_review_required, review_status, raw_response, created_at) VALUES ('290caea0-a729-40a5-9645-4ef6af248c93', '017b408e-dd7e-446e-b314-bbcdf2c5bb74', '8de51528-6e41-43f1-8e3a-7188e22481f2', '09431308-7ff1-4606-b5b1-3d3189d85e0f', 'pricing_and_feature_inquiry', 'IT/ERP Advisory & Specialist Finance Recruitment', 'Ciaran Walsh (SaaS CTO/Founder) evaluating QuickBooks to NetSuite/Sage Intacct ERP migration, and requires senior ACA/ACCA Financial Controller recruitment.', 0.94, 'Hi Ciaran, yes absolutely. SENVO provides dedicated cloud ERP architecture advisory (including SaaS revenue recognition compliance under IFRS 15) alongside our specialized finance executive search practice for ACA/ACCA senior controllers. We can arrange a 20-minute consultation with both our Systems and Recruitment leads.', 'Coordinate joint ERP Solutions & Finance Talent introductory call', 1, 'approved', NULL, '2026-10-29T10:43:37.082Z') ON CONFLICT DO NOTHING;
INSERT INTO senvo_outreach.ai_assessments (id, conversation_id, message_id, lead_id, intent, requested_service, summary, confidence, suggested_reply, suggested_next_action, human_review_required, review_status, raw_response, created_at) VALUES ('a3247920-6a6b-4b77-9451-016417898c9e', 'f3b27ab6-a4df-4408-817f-1fb010292d6c', 'f59f51cf-fb99-4980-99a6-766d62ead7c6', 'c31bfaf9-96a7-4a9b-8451-12f9d372a43b', 'feature_and_timeline_inquiry', 'Managed Irish Payroll Bureau (85 staff)', 'Mairead Kelly requires managed payroll bureau services for 85 multi-branch retail staff, focusing on PAYE modernization and pension compliance.', 0.95, 'Hello Mairead! Our managed Irish payroll bureau routinely handles multi-location workforces with weekly/monthly rosters, full Revenue ROS synchronization, and digital employee payslips. Onboarding typically takes 7 to 10 business days with parallel test runs. Would you be free for a brief call tomorrow morning at 10:00 AM?', 'Schedule payroll scope review call with Mairead Kelly (Limerick Group)', 1, 'approved', NULL, '2026-10-29T10:43:37.082Z') ON CONFLICT DO NOTHING;
INSERT INTO senvo_outreach.ai_assessments (id, conversation_id, message_id, lead_id, intent, requested_service, summary, confidence, suggested_reply, suggested_next_action, human_review_required, review_status, raw_response, created_at) VALUES ('c3abff4b-b7cf-499f-ba10-b3aa4b6547c1', 'e1fea61a-764d-41c8-a42c-45102396f98b', '881b711a-ec8d-4b6c-aaea-f66892ece354', 'ed51e305-f27b-4c9d-a8e3-e4275a697289', 'corporate_services_inquiry', 'Company Secretarial & Registered Office Facility', 'Inquiry regarding Dublin prime registered office facility and Section 137 director bond support for international corporate structures.', 0.92, 'Hello Brendan, yes we provide prime Dublin registered office facilities, complete CRO annual filing administration, statutory register maintenance, and assistance with Section 137 Non-Resident Director Bonds. We would be pleased to share our corporate secretarial schedule.', 'Provide Company Secretarial service package details to Brendan Byrne', 1, 'approved', NULL, '2026-10-29T10:43:37.082Z') ON CONFLICT DO NOTHING;

